@10 n="soft_coordination_cv" d="Occupancy-weighted coefficient of variation of site soft coordination, measuring inequivalent local connectivity." B=1176
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    first = 0.0
    second = 0.0
    amount = 0.0
    for i in range(n):
        if occ[i] <= 0 or radii[i] <= 0:
            continue
        coordination = 0.0
        for edge in edges:
            if edge.get('i') != i:
                continue
            j = edge.get('j')
            d = edge.get('distance_A') or 0.0
            if j is None or j < 0 or j >= n or d <= 0 or radii[j] <= 0:
                continue
            coordination += occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
        first += occ[i] * coordination
        second += occ[i] * coordination * coordination
        amount += occ[i]
    if amount <= 0 or first <= 0:
        return 0.0
    mean = first / amount
    variance = max(0.0, second / amount - mean * mean)
    return float(variance ** 0.5 / mean)
@end
